/** `puppeteer-core.launch` in facade form: every call is a traced Effect of a Browser. */
export const launch: Effectify.EffectFunction<typeof Upstream.launch, Failure, Handles> = Effectify.entry<typeof Upstream.launch, Failure, Handles>(Upstream.launch, "launch", kinds.Browser, kinds, classify, { signal: { index: 0, property: "signal" } });

/** A puppeteer-core `Browser` as a service; `layer` provides the one `make` acquires (`launch` in facade form), released with the layer. */
export class PuppeteerBrowser extends Context.Service<PuppeteerBrowser, Browser>()("@effectified/puppeteer-core/PuppeteerBrowser") {
	static readonly layer = <E>(make: Effect.Effect<Browser, E, Scope.Scope>) => Layer.effect(PuppeteerBrowser, make);
}

/** A WebMCP to name its listeners' arguments by, through its own `on<K>`: types only, never read at run time. */
declare const emitterOfWebMCP: Upstream.WebMCP;

/**
 * Events of the wrapped handles as Streams of each emission's arguments, as upstream types them, listening for as
 * long as the stream runs, under a span `<Handle>.events.<event>`. An emitter cannot be paused: the buffer is
 * unbounded unless `options` bounds it (`{ bufferSize: 16 }` keeps the newest, `strategy: "dropping"` the oldest).
 */
export const events = {
	WebMCP: {
		toolinvoked: (handle: WebMCP, options?: Effectify.EventOptions) => Effectify.events<Parameters<Parameters<typeof emitterOfWebMCP.on<"toolinvoked">>[1]>>(handle.upstream, "toolinvoked", "WebMCP.events.toolinvoked", options),
		toolresponded: (handle: WebMCP, options?: Effectify.EventOptions) => Effectify.events<Parameters<Parameters<typeof emitterOfWebMCP.on<"toolresponded">>[1]>>(handle.upstream, "toolresponded", "WebMCP.events.toolresponded", options),
		toolsadded: (handle: WebMCP, options?: Effectify.EventOptions) => Effectify.events<Parameters<Parameters<typeof emitterOfWebMCP.on<"toolsadded">>[1]>>(handle.upstream, "toolsadded", "WebMCP.events.toolsadded", options),
		toolsremoved: (handle: WebMCP, options?: Effectify.EventOptions) => Effectify.events<Parameters<Parameters<typeof emitterOfWebMCP.on<"toolsremoved">>[1]>>(handle.upstream, "toolsremoved", "WebMCP.events.toolsremoved", options),
	},
};
